"""Generate isolated native target dummy lifecycle while retaining native DPS and configuration."""
import ast
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
tree=ast.parse((ROOT/'tools/generate-layer-families.py').read_text(encoding='utf-8'))
guard=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='guard' for t in n.targets))
guard=guard.replace('@Override public void damage(float amount){owner.damage(this,amount);}','')
text='''package fpv.construction;
// Generated by tools/generate-layer-target-dummy.py.
import arc.math.geom.Geometry;
import mindustry.gen.*;
import mindustry.game.Team;
import mindustry.world.*;
import mindustry.world.blocks.defense.TargetDummy;
import mindustry.world.blocks.defense.TargetDummy.TargetDummyBuild;

/** Original target dummy unit/DPS with an explicit layer-owned spawn and tether boundary. */
final class LayerTargetDummyFamilies {
    static boolean supports(Class<?> type){return type==TargetDummyBuild.class;}
    static Building create(LayerBuildingAdapter owner,Block block,Class<?> type){
        if(!supports(type))throw new IllegalArgumentException("Unsupported upper target dummy");
        return ((TargetDummy)block).new TargetDummyBuild(){
'''
text+='\n'.join('            '+line for line in guard.strip().splitlines())
text+='''
            @Override public void updateTile(){if(LayerTargetDummyBehavior.prepare(owner,this))super.updateTile();}
            @Override public void spawned(int id){readUnitId=id;}
            @Override public void read(arc.util.io.Reads read,byte revision){super.read(read,revision);LayerTargetDummyBehavior.validate(this);}
        };
    }
    static boolean configure(Building building,Object value){return building instanceof TargetDummyBuild dummy&&LayerTargetDummyBehavior.configure(dummy,value);}
    static void reconcileReferences(LayerBuildingAdapter owner){for(var entry:owner.entries())if(entry.building() instanceof TargetDummyBuild dummy)LayerTargetDummyBehavior.reconcile(dummy);}
}
'''
(ROOT/'src/main/java/fpv/construction/LayerTargetDummyFamilies.java').write_text('\n'.join(line.rstrip() for line in text.splitlines())+'\n',encoding='utf-8')
print('Generated target dummy adapter')
